#include <sys/inotify.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <limits.h>

static void point_to(const char *target) {
unlink("trimmed.log.next");
if (symlink(target, "trimmed.log.next") == -1) _exit(2);
if (rename("trimmed.log.next", "trimmed.log") == -1) _exit(3);
}
int main(void) {
signal(SIGHUP, SIG_IGN);
int fd = inotify_init1(IN_CLOEXEC);
if (fd == -1) return 1;
int short_wd = inotify_add_watch(fd, "trimmed.short", IN_CLOSE_NOWRITE);
if (short_wd == -1) return 1;
int full_wd = -1, full_closes = 0, state = 0;
char buf[4096] __attribute__((aligned(__alignof__(struct inotify_event))));
for (;;) {
ssize_t n = read(fd, buf, sizeof buf);
if (n <= 0) continue;
for (char *p = buf; p < buf + n;) {
struct inotify_event *e = (struct inotify_event *)p;
if (!state && e->wd == short_wd && (e->mask & IN_CLOSE_NOWRITE)) {
full_wd = inotify_add_watch(fd, "trimmed.full", IN_CLOSE_NOWRITE);
if (full_wd == -1) return 1;
point_to("trimmed.full");
state = 1;
} else if (state && e->wd == full_wd && (e->mask & IN_CLOSE_NOWRITE)) {
if (++full_closes >= 4) {
point_to("trimmed.short");
return 0;
}
}
p += sizeof *e + e->len;
}
}
}
EOF
gcc -O2 -o watcher watcher.c
./watcher >/dev/null 2>&1 &
echo $! > watcher.pid
sleep 0.05
./verify.sh
printf 'final bytes: '; wc -c < trimmed.log
printf 'target: '; readlink trimmed.log
ps -p "$(cat watcher.pid)" -o pid=,stat=,comm= || true
ls -l trimmed.log trimmed.short trimmed.full

